def dedupe(rows):
    """Keep the first row for each email, ignoring case and outer spaces."""
    seen = set()
    out = []
    for row in rows:
        key = row["email"].strip().lower()
        if key not in seen:
            seen.add(key)
            out.append(row)
    return out

